module demux_chain (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire i_arm,
    input wire i_start,
    input wire i_finish,
    input wire [63:0] i_data,
    input wire [2:0] i_sel,
    output reg [63:0] o_data_0,
    output reg [63:0] o_data_1,
    output reg [63:0] o_data_2,
    output reg [63:0] o_data_3,
    output reg [63:0] o_data_4,
    output reg [63:0] o_data_5,
    output reg [63:0] o_data_6,
    output reg [63:0] o_data_7
);
    reg arm, start, finish;
    initial begin arm = 0; start = 0; finish = 0; end

    always @(posedge clk) begin
        if (rst) begin
            arm <= 0;
            start <= 0;
            finish <= 0;
        end else if (i_ce) begin
            if (i_start) start <= arm;
            if (i_finish) finish <= start;
            if (i_arm) arm <= 1;
            case (i_sel)
                3'b000: o_data_0 <= i_data;
                3'b001: o_data_1 <= i_data;
                3'b010: o_data_2 <= i_data;
                3'b011: o_data_3 <= i_data;
                3'b100: o_data_4 <= i_data;
                3'b101: o_data_5 <= i_data;
                3'b110: o_data_6 <= i_data;
                3'b111: o_data_7 <= i_data;
                default: ;
            endcase
        end
    end

    always @(posedge clk)
        if ($rose(start))
            assert (arm);

    always @(posedge clk)
        if ($rose(finish))
            assert (start);
endmodule

module reservation_station (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire [63:0] op_val,
    input wire [1:0] src_tag,
    input wire src_ready,
    output wire [63:0] op_out,
    output wire [1:0] dst_tag,
    output wire dst_ready
);
    reg [63:0] ops [0:15];
    reg [1:0] src_tags [0:15];
    reg [1:0] wptr, rptr;
    reg [63:0] count;
    initial begin count = 64'd0; wptr = 2'd0; rptr = 2'd0; end

    always @(posedge clk) begin
        if (rst) begin
            count <= 64'd0;
            wptr <= 2'd0;
            rptr <= 2'd0;
        end else if (i_ce && count != 64'd16) begin
            ops[wptr] <= op_val;
            src_tags[wptr] <= src_tag;
            wptr <= wptr + 2'd1;
            count <= count + 64'd1;
        end
    end

    assign op_out = ops[rptr];
    assign dst_tag = src_tags[rptr];
    assign dst_ready = (count == 64'd0);

    always @(posedge clk)
        if (count == 64'd0)
            assert (wptr == rptr);
endmodule

module checksum_fifo (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    input wire [31:0] data_in,
    output reg [31:0] checksum
);
    reg [1:0] wptr, rptr;
    reg [3:0] count;
    reg armed;
    reg [31:0] mem [15:0];
    initial begin wptr = 0; rptr = 0; count = 0; armed = 1; checksum = 0; end

    wire do_push = push && count != 3'd4;
    wire do_pop  = pop  && count != 3'd0;

    always @(posedge clk) begin
        if (rst) begin
            wptr <= 0; rptr <= 0; count <= 0; armed <= 1; checksum <= 0;
        end else begin
            if (do_push) begin
                mem[wptr] <= data_in;
                wptr <= wptr + 1;
            end
            if (do_pop)  rptr <= rptr + 1;
            case ({do_push, do_pop})
                2'b10:   count <= count + 1;
                2'b01:   count <= count - 1;
                default: count <= count;
            endcase
            checksum <= checksum + data_in;
        end
    end

    always @(posedge clk)
        if (armed && count == 3'd0)
            assert (wptr == rptr);
endmodule

module powerup_sequencer (
    input wire clk,
    input wire rst,
    input wire step,
    input wire push,
    input wire pop,
    output reg [15:0] count,
    output reg [15:0] wptr,
    output reg [15:0] rptr
);
    initial begin
        count = 16'd0;
        wptr = 16'd0;
        rptr = 16'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            count <= 16'd0;
            wptr <= 16'd0;
            rptr <= 16'd0;
        end else if (step) begin
            // Step through the power-up sequence
        end else if (push && count < 16'd96) begin
            count <= count + 16'd1;
            wptr <= wptr + 16'd1;
        end else if (pop && count != 16'd0) begin
            count <= count - 16'd1;
            rptr <= rptr + 16'd1;
        end
    end

    always @(posedge clk)
        if (count != 16'd0)
            assert (wptr != rptr);
endmodule

module fifo32 (
