    always @(posedge clk) begin
        if (rst) begin
            count <= 32'd0;
            wptr <= 2'd0;
            rptr <= 2'd0;
        end else if (i_ce && count != 32'd8) begin
            mem[wptr] <= i_data;
            wptr <= wptr + 2'd1;
            count <= count + 32'd1;
        end
    end

    assign o_data = mem[rptr];
    assign empty = (count == 32'd0);
    assign full = (count == 32'd8);

    always @(posedge clk)
        if (count == 32'd0)
            assert (wptr == rptr);
endmodule

module sram_buffer (
    input wire clk,
    input wire rst,
    input wire step,
    input wire wr_en,
    input wire rd_en,
    input wire [63:0] wr_data,
    output reg [63:0] rd_data,
    output reg [63:0] count,
    output reg [63:0] wptr,
    output reg [63:0] rptr,
    output reg [5:0][63:0] data
);
    initial begin
        count = 64'd0;
        wptr = 64'd0;
        rptr = 64'd0;
        data = {6{64'd0}};
    end

    always @(posedge clk) begin
        if (rst) begin
            count <= 64'd0;
            wptr <= 64'd0;
            rptr <= 64'd0;
            data <= {6{64'd0}};
        end else if (step) begin
            if (wr_en && count < 64'd6) begin
                data[wptr[2:0]] <= wr_data;
                wptr <= wptr + 64'd1;
                count <= count + 64'd1;
            end else if (rd_en && count != 64'd0) begin
                rd_data <= data[rptr[2:0]];
                rptr <= rptr + 64'd1;
                count <= count - 64'd1;
            end
        end
    end

    always @(posedge clk)
        assert (count == 64'd0 || count == 64'd1 || count == 64'd2 || count == 64'd3 || count == 64'd4 || count == 64'd5 || count == 64'd6);

    always @(posedge clk)
        assert (count != 64'd0 || wptr == rptr);

    reg arm = 0;
    always @(posedge clk) arm <= (count != 64'd0);
    cover property (arm && count == 64'd1);
endmodule

module paged_ram (
    input wire i_clk,
    input wire i_reset,
    input wire i_ce,
    input wire [2:0] i_wdata,
    input wire [2:0] i_addr,
    input wire i_we,
    input wire i_arm,
    output wire [2:0] o_rdata
);
    reg [7:0] count;
    reg [7:0] page;
    reg [2:0] mem [0:7];
    reg armed;
    initial count = 8'd0;
    initial page = 8'd0;
    initial armed = 1'b0;

    always @(posedge i_clk)
        if (i_reset) begin
            count <= 8'd0;
            page <= 8'd0;
            armed <= 1'b0;
        end else begin
            if (i_ce) begin
                if (i_we && count < 8'd8)
                    mem[count] <= i_wdata;
                count <= (count >= 8'd7) ? 8'd0 : count + 8'd1;
            end
            if (i_arm)
                armed <= 1'b1;
        end

    assign o_rdata = mem[(page << 3) + count];

    always @(posedge i_clk)
        if (armed)
            assert (count < 8'd128);
endmodule

module filter_coefficients (
    input wire clk,
    input wire rst,
    input wire i_ce,
    output reg [31:0] coeff
);
    reg [31:0] rom [0:255];
