        if (rst) begin
            count <= 32'd0;
            wptr <= 2'd0;
            rptr <= 2'd0;
        end else if (i_ce) begin
            if (count < 32'd256) begin
                count <= count + 32'd1;
                wptr <= wptr + 2'd1;
            end
        end
    end

    always @(posedge clk)
        coeff <= rom[rptr];

    reg pv = 0;
    always @(posedge clk) pv <= 1;
    always @(posedge clk) if (pv && count != 32'd0)
        assert (wptr == (rptr + count[1:0]));
endmodule

module interrupt_status_aggregator (
    input wire clk,
    input wire rst,
    input wire i_push,
    input wire i_pop,
    input wire [31:0] i_src,
    input wire [3:0] i_mask,
    output wire [31:0] o_raw,
    output wire [31:0] o_mask,
    output wire [31:0] o_mskd
);
    reg [31:0] raw [0:3];
    reg [3:0] mask [0:3];
    reg [31:0] mskd [0:3];
    reg [31:0] count, wptr, rptr;
    initial begin count = 32'd0; wptr = 32'd0; rptr = 32'd0; end

    always @(posedge clk) begin
        if (rst) begin
            count <= 32'd0;
            wptr <= 32'd0;
            rptr <= 32'd0;
        end else if (i_push && count != 32'd4) begin
            raw[wptr[1:0]] <= i_src;
            mask[wptr[1:0]] <= i_mask;
            mskd[wptr[1:0]] <= (i_src & {32{i_mask[0]}}) |
                                  (i_src & {32{i_mask[1]}}) |
                                  (i_src & {32{i_mask[2]}}) |
                                  (i_src & {32{i_mask[3]}});
            count <= count + 32'd1;
            wptr <= wptr + 32'd1;
        end else if (i_pop && count != 32'd0) begin
            count <= count - 32'd1;
            rptr <= rptr + 32'd1;
        end
    end

    assign o_raw = (count == 32'd0) ? 32'd0 : raw[rptr[1:0]];
    assign o_mask = (count == 32'd0) ? 4'b0000 : mask[rptr[1:0]];
    assign o_mskd = (count == 32'd0) ? 32'd0 : mskd[rptr[1:0]];

    always @(*)
        if (count == 32'd0)
            assert (wptr == rptr);
endmodule

module turbo_siso (
    input wire i_clk,
    input wire i_reset,
    input wire i_ce,
    input wire [15:0] i_input,
    output wire [15:0] o_output
);
    reg [15:0] alpha [15:0];
    reg [15:0] beta [15:0];
    reg window;
    initial begin
        window = 1'b0;
        for (int i = 0; i < 16; i++) begin
            alpha[i] = 16'd0;
            beta[i] = 16'd0;
        end
    end

    always @(posedge i_clk)
        if (i_reset) begin
            window <= 1'b0;
            for (int i = 0; i < 16; i++) begin
                alpha[i] <= 16'd0;
                beta[i] <= 16'd0;
            end
        end else if (i_ce) begin
            window <= 1'b1;
            alpha[0] <= i_input;
            beta[0] <= i_input;
            for (int i = 1; i < 16; i++) begin
                alpha[i] <= alpha[i-1] + 16'd1;
                beta[i] <= beta[i-1] + 16'd1;
            end
        end

    assign o_output = window ? (alpha[15] - beta[15]) : 16'd0;

    assert property (window == 1'b0 || (alpha[0] == beta[0] && alpha[1] == beta[1] && alpha[2] == beta[2] && alpha[3] == beta[3] && alpha[4] == beta[4] && alpha[5] == beta[5] && alpha[6] == beta[6] && alpha[7] == beta[7] && alpha[8] == beta[8] && alpha[9] == beta[9] && alpha[10] == beta[10] && alpha[11] == beta[11] && alpha[12] == beta[12] && alpha[13] == beta[13] && alpha[14] == beta[14] && alpha[15] == beta[15]));
endmodule

module wavefront (
    input wire clk,
