    input wire i_ce,
    output wire [47:0] o_diag,
    output wire [47:0] o_count
);
    reg [31:0] diag, count;
    reg window;
    initial begin diag = 32'd0; count = 32'd48; window = 1'b0; end

    always @(posedge clk) begin
        if (rst) begin
            diag <= 32'd0;
            count <= 32'd48;
            window <= 1'b0;
        end else if (i_ce) begin
            if (count != 32'd0) begin
                window <= 1'b1;
                diag <= diag + 32'd1;
                count <= count - 32'd1;
            end else begin
                window <= 1'b0;
            end
        end
    end

    assign o_diag = diag;
    assign o_count = count;

    always @(posedge clk)
        if (window)
            assert (diag + count == 32'd48);
endmodule

module bitfield_extractor (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    input wire [15:0] in_source,
    input wire [3:0] in_offset,
    input wire [3:0] in_length,
    output reg [2:0] count,
    output reg [15:0] source,
    output reg [15:0] extracted_field,
    output reg [3:0] offset,
    output reg [3:0] length
);
    initial begin source = 16'd0; extracted_field = 16'd0; offset = 4'd0; length = 4'd1; count = 3'd0; end

    wire do_push = push && count != 3'd32;
    wire do_pop  = pop  && count != 3'd0;

    always @(posedge clk) begin
        if (rst) begin
            source <= 16'd0; extracted_field <= 16'd0; offset <= 4'd0; length <= 4'd1; count <= 3'd0;
        end else begin
            if (do_push) begin
                source <= in_source;
                offset <= in_offset;
                length <= in_length;
                extracted_field <= (source >> offset) & ((1 << length) - 1);
                count <= count + 1;
            end else if (do_pop) begin
                count <= count - 1;
            end
        end
    end

    always @(*)
        assert (extracted_field == ((source >> offset) & ((1 << length) - 1)));
endmodule

module keypad_encoder (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire [63:0] i_matrix,
    output reg [63:0] o_key_code,
    output reg o_key_pressed,
    output wire [5:0] o_row_drive
);
    reg [5:0] row_scan;
    reg [63:0] elapsed, remaining;
    initial begin row_scan = 6'd0; elapsed = 64'd0; remaining = 64'd48; end

    always @(posedge clk) begin
        if (rst) begin
            row_scan <= 6'd0;
            elapsed <= 64'd0;
            remaining <= 64'd48;
            o_key_code <= 64'd0;
            o_key_pressed <= 1'b0;
        end else if (i_ce) begin
            if (remaining != 64'd0) begin
                elapsed <= elapsed + 64'd1;
                remaining <= remaining - 64'd1;
            end
            if (row_scan != 6'd47) begin
                row_scan <= row_scan + 6'd1;
            end else begin
                row_scan <= 6'd0;
                if (remaining == 64'd0) begin
                    o_key_code <= i_matrix;
                    o_key_pressed <= 1'b1;
                end
            end
        end
    end

    assign o_row_drive = (64'd1 << row_scan);

    always @(posedge clk)
        if ($rose(remaining == 64'd0))
            assert (elapsed == 64'd48);
endmodule

