module pwm64 (
    input wire clk,
    input wire rst,
    input wire i_ce,
    output reg pwm_out,
    output reg [63:0] o_up,
    output reg [63:0] o_down,
    output reg dir
);
    reg [63:0] period = 64'd127;
    reg [63:0] compare = 64'd64;
    reg [63:0] up, down;
    initial begin up = 64'd0; down = 64'd127; dir = 1'b0; end

    always @(posedge clk) begin
        if (rst) begin
            up <= 64'd0;
            down <= 64'd127;
            dir <= 1'b0;
        end else if (i_ce) begin
            if (dir == 1'b0) begin
                if (up < compare) begin
                    up <= up + 64'd1;
                    down <= down - 64'd1;
                end else begin
                    dir <= 1'b1;
                end
            end else begin
                if (down < compare) begin
                    up <= up - 64'd1;
                    down <= down + 64'd1;
                end else begin
                    dir <= 1'b0;
                end
            end
        end
    end

    always @(*)
        if (dir == 1'b0)
            pwm_out = (up < compare);
        else
            pwm_out = (down < compare);

    assign o_up = up;
    assign o_down = down;

    always @(posedge clk)
        if (dir == 1'b0)
            assert (up <= compare);
    always @(posedge clk)
        if (dir == 1'b1)
            assert (down <= compare);
endmodule

