    input wire read,
    input wire write,
    input wire [31:0] addr,
    input wire [31:0] wdata,
    output reg [31:0] rdata
);
    reg [31:0] mem [255:0];
    reg [31:0] page_reg;
    reg [31:0] last_write_page;
    reg [31:0] last_read_page;
    reg last_was_write;
    reg armed;

    initial begin
        page_reg = 32'h00000000;
        last_write_page = 32'h00000000;
        last_read_page = 32'h00000000;
        last_was_write = 1'b0;
        armed = 1'b1;
    end

    always @(posedge clk) begin
        if (rst) begin
            page_reg <= 32'h00000000;
            last_write_page <= 32'h00000000;
            last_read_page <= 32'h00000000;
            last_was_write <= 1'b0;
            armed <= 1'b1;
        end else if (i_ce) begin
            if (write) begin
                mem[addr] <= wdata;
                last_write_page <= page_reg;
                last_was_write <= 1'b1;
            end else if (read) begin
                rdata <= mem[addr];
                last_read_page <= page_reg;
                last_was_write <= 1'b0;
            end
        end
    end

    always @(*)
        if (armed && !last_was_write)
            assert (last_read_page == last_write_page);
endmodule

module matrix_arbiter (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    output reg [63:0] count,
    output reg [63:0] wptr,
    output reg [63:0] rptr,
    output reg window
);
    reg [63:0] matrix [0:63][0:63];
    initial begin
        count = 64'd0;
        wptr = 64'd0;
        rptr = 64'd0;
        window = 1'b0;
        for (int i = 0; i < 64; i++)
            for (int j = 0; j < 64; j++)
                matrix[i][j] = 1'b0;
    end

    wire do_push = push && count != 64'd64;
    wire do_pop  = pop  && count != 64'd0;

    always @(posedge clk) begin
        if (rst) begin
            count <= 64'd0;
            wptr <= 64'd0;
            rptr <= 64'd0;
            window <= 1'b0;
            for (int i = 0; i < 64; i++)
                for (int j = 0; j < 64; j++)
                    matrix[i][j] <= 1'b0;
        end else begin
            if (do_push) wptr <= wptr + 64'd1;
            if (do_pop)  rptr <= rptr + 64'd1;
            case ({do_push, do_pop})
                2'b10:   count <= count + 64'd1;
                2'b01:   count <= count - 64'd1;
                default: count <= count;
            endcase
            window <= do_push;
        end
    end

    always @(posedge clk)
        if (window)
            assert (count != 64'd0 || wptr == rptr);
    always @(posedge clk)
        if (window)
            assert (count == 64'd0 || wptr != rptr);
endmodule
